fn frame(t: i32) {
    host::display::clear(0x0c0c14);
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, host::compose::spawn_lib("lib-notes"));
    }
    let h: i32 = host::display::state_get(1);
    let step: i32 = (t / 20) % 8;
    if t % 20 == 0 {
        let mut f: i32 = 440;
        let mut src: i32 = 0;
        if host::compose::status(h) == 1 {
            let lf: i32 = host::compose::call(h, "freq", step, 0, 0, 0);
            if host::compose::call_ok() == 0 {
                f = lf;
                src = 1;
            }
        }
        host::audio::tone(f, 160, 0);
        host::display::state_set(2, f);
        host::display::state_set(3, src);
    }
    if host::display::state_get(3) == 1 {
        host::display::draw_string(8, 8, "PITCHES: LIB-NOTES", 0x00ff66, 1);
    } else {
        host::display::draw_string(8, 8, "PITCHES: FALLBACK A440", 0xffff00, 1);
    }
    host::display::draw_number(8, 26, host::display::state_get(2), 0xffffff, 2);
    let mut i: i32 = 0;
    while i < 8 {
        let mut c: i32 = 0x303040;
        if i == step { c = 0x00ffcc; }
        host::display::fill_rect(20 + i * 60, 200, 48, 48, c);
        i = i + 1;
    }
    host::display::present();
}
